  function journey(id){const values=JOURNEY_TRANSLATIONS[language],index=JOURNEY_IDS.indexOf(id);if(!values||index<0)return null;const titleKey=JOURNEY_TITLE_KEYS[id];return{title:titleKey?t(titleKey):'HOOD',description:values.d[index],macros:values.m[index],detail:term('ready'),phaseLabel:values.phase,stateLabel:values.state}}
